struct Context;
struct Expr { virtual ~Expr() = default; virtual long eval(const Context&) const = 0; };
struct Num final : Expr { long v; long eval(const Context&) const override { return v; } };
struct Add final : Expr {
    std::unique_ptr<Expr> l, r;
    long eval(const Context& c) const override { return l->eval(c) + r->eval(c); }
};
